export const xml2json = (xml) => {
    const splittedXml = xml.split('\n');
    const coords = [
        ['w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'e', 'w'],
        ['w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w', 'w'],
    ];
    const result = { level: 0, coords: coords };
    let state = '';
    let row = -1;
    let column = -1;
    const lvlRegExp = /level>(\d+)/i;
    const spRegExp = /<startpoint/i;
    const epRegExp = /<escapepoint/i;
    const wallRegExp = /<wall/i;
    const rowRegExp = /row>(\d+)/i;
    const columnRegExp = /column>(\d+)/i;
    splittedXml.forEach(line => {
        const levelMatch = line.match(lvlRegExp);
        const spMatch = line.match(spRegExp);
        const epMatch = line.match(epRegExp);
        const wallMatch = line.match(wallRegExp);
        if (levelMatch) {
            result.level = +levelMatch[1];
        }
        if (spMatch) {
            state = 's';
        }
        else if (epMatch) {
            state = 'x';
        }
        else if (wallMatch) {
            state = 'w';
        }
        if (['s', 'x', 'w'].includes(state)) {
            const rowMatch = line.match(rowRegExp);
            const columnMatch = line.match(columnRegExp);
            if (rowMatch) {
                row = +rowMatch[1] - 1;
            }
            else if (columnMatch) {
                column = +columnMatch[1] - 1;
            }
            if (column >= 0 && row >= 0) {
                result.coords[row][column] = state;
                row = -1;
                column = -1;
                state = '';
            }
        }
    });
    console.log(result.coords);
};
